aot-command:
cd wabt/wasm2c && ../build/wasm2c --enable-threads --enable-custom-page-sizes --enable-compact-imports --module-name module {input} -o temp.c && entry=$(grep -oE 'w2c_module_0x5Fstart|w2c_module_main' temp.h | sort -u | head -1) && echo '#include <stdio.h>
#include <stdlib.h>
#include "temp.h"
int main(int argc, char** argv) {{
  wasm_rt_init();
  w2c_module instance;
  wasm2c_module_instantiate(&instance);
  '"$entry"'(&instance);
  wasm2c_module_free(&instance);
  wasm_rt_free();
  return 0;
}}' > main.c && gcc main.c temp.c wasm-rt-impl.c wasm-rt-mem-impl.c wasm-rt-exceptions-impl.c -lm -o {output} && rm temp.c temp.h main.c
